44	// Binary operation matcher and extractor
45	using BinaryMatcher = std::function<bool(const PrimExpr &)>;
46	using BinaryExtractor =
47	    std::function<void(const PrimExpr &, PrimExpr *, PrimExpr *)>;
48	
49	struct BinaryOpInfo {
50	  Op op_type;
51	  BinaryMatcher matcher;
52	  BinaryExtractor extractor;
53	};
54	
55	// Create binary operation table
56	inline std::vector<BinaryOpInfo> CreateBinaryOpTable() {
57	  std::vector<BinaryOpInfo> table;
58	
59	  // Template for arithmetic operations
60	  auto add_arith_op = [&table](Op name, auto matcher_fn, auto cast_fn) {
61	    table.push_back(
62	        {name,
63	         [matcher_fn](const PrimExpr &e) { return matcher_fn(e) != nullptr; },
64	         [cast_fn](const PrimExpr &e, PrimExpr *a, PrimExpr *b) {
65	           auto node = cast_fn(e);
66	           *a = node->a;
67	           *b = node->b;
68	         }});
69	  };
70	
71	  add_arith_op(
72	      tl::ascend_add(), [](const PrimExpr &e) { return e.as<AddNode>(); },
73	      [](const PrimExpr &e) { return e.as<AddNode>(); });
74	
75	  add_arith_op(
76	      tl::ascend_sub(), [](const PrimExpr &e) { return e.as<SubNode>(); },
77	      [](const PrimExpr &e) { return e.as<SubNode>(); });
78	
79	  add_arith_op(
80	      tl::ascend_mul(), [](const PrimExpr &e) { return e.as<MulNode>(); },
81	      [](const PrimExpr &e) { return e.as<MulNode>(); });
82	
83	  add_arith_op(
84	      tl::ascend_div(), [](const PrimExpr &e) { return e.as<DivNode>(); },
85	      [](const PrimExpr &e) { return e.as<DivNode>(); });
86	
87	  add_arith_op(
88	      tl::ascend_min(), [](const PrimExpr &e) { return e.as<MinNode>(); },
89	      [](const PrimExpr &e) { return e.as<MinNode>(); });
90	
91	  add_arith_op(
92	      tl::ascend_max(), [](const PrimExpr &e) { return e.as<MaxNode>(); },
93	      [](const PrimExpr &e) { return e.as<MaxNode>(); });
94	
95	  // Template for builtin call operations
96	  auto add_builtin_op = [&table](Op name, auto builtin_fn) {
97	    table.push_back({name,
98	                     [builtin_fn](const PrimExpr &e) {
99	                       auto call = e.as<CallNode>();
100	                       return call && call->op.same_as(builtin_fn());
101	                     },
102	                     [](const PrimExpr &e, PrimExpr *a, PrimExpr *b) {
103	                       auto call = e.as<CallNode>();
104	                       if (call && call->args.size() >= 2) {
105	                         *a = call->args[0];
106	                         *b = call->args[1];
107	                       }
108	                     }});
109	  };
110	
111	  add_builtin_op(tl::ascend_bitwise_and(), builtin::bitwise_and);
112	  add_builtin_op(tl::ascend_bitwise_or(), builtin::bitwise_or);
113	  add_builtin_op(tl::ascend_bitwise_lshift(), builtin::shift_left);
114	  add_builtin_op(tl::ascend_bitwise_rshift(), builtin::shift_right);
115	  add_builtin_op(tl::ascend_bitwise_and(), tl::ascend_bitwise_and);
116	  add_builtin_op(tl::ascend_bitwise_or(), tl::ascend_bitwise_or);
117	  add_builtin_op(tl::ascend_bitwise_lshift(), tl::ascend_bitwise_lshift);
118	  add_builtin_op(tl::ascend_bitwise_rshift(), tl::ascend_bitwise_rshift);
119	  return table;
120	}
