131	class AscendLowerParallelToVector : public arith::IRMutatorWithAnalyzer {
132	public:
133	  static PrimFunc Substitute(PrimFunc f) {
134	    arith::Analyzer analyzer;
135	    AscendLowerParallelToVector substituter(&analyzer);
136	    PrimFuncNode *fptr = f.CopyOnWrite();
137	    fptr->body = substituter.VisitStmt(f->body);
138	    return GetRef<PrimFunc>(fptr);
139	  }
140	
141	private:
142	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
143	
144	  const VarNode *vector_dim_var_ = nullptr;
145	  const VarNode *outer_dim_var_ = nullptr;
146	  bool is_2d_vectorizing_ = false;
147	  int temp_buffer_id_ = 0;
148	  std::vector<Buffer> temp_buffers_;
149	  int64_t vector_dim_extent_{
150	      0};                       // Track the extent of the vector dimension loop
151	  int64_t outer_dim_extent_{0}; // Track the extent of the outer dimension loop
152	
153	  Buffer CreateTempBufferLike(const Buffer &ref, int64_t num_elements,
154	                              int64_t inner_vec_len = 0) {
155	    DataType dtype = ref->dtype;
156	
157	    if (num_elements < 0) {
158	      LOG(FATAL) << "Cannot create temp buffer for non-constant shape.";
159	      return Buffer();
160	    }
161	
162	    Var data(ref->name + "_tmp_" + std::to_string(temp_buffer_id_++) + "_data",
163	             PointerType(PrimType(dtype), "shared.ub"));
164	
165	    // Determine the shape based on the actual computation size (loop extent)
166	    Array<PrimExpr> shape;
167	    if (ref->shape.size() == 1) {
168	      // 1D case: just the total elements
169	      shape.push_back(IntImm(DataType::Int(32), num_elements));
170	    } else if (ref->shape.size() >= 2) {
171	      // 2D or higher: use the computation dimensions
172	      // If inner_vec_len is provided, use it to determine the shape
173	      if (inner_vec_len > 0) {
174	        int64_t outer_extent = num_elements / inner_vec_len;
175	        shape.push_back(IntImm(DataType::Int(32), outer_extent));
176	        shape.push_back(IntImm(DataType::Int(32), inner_vec_len));
177	      } else {
178	        // Fall back to 1D if we can't determine 2D shape
179	        shape.push_back(IntImm(DataType::Int(32), num_elements));
180	      }
181	    }
182	
183	    Buffer buf = Buffer(data, dtype, shape,
184	                        /*strides=*/{},
185	                        /*elem_offset=*/PrimExpr(0),
186	                        /*name=*/data->name_hint,
187	                        /*data_alignment=*/0,
188	                        /*offset_factor=*/0,
189	                        /*buffer_type=*/kDefault);
190	
191	    temp_buffers_.push_back(buf);
192	    return buf;
193	  }
