214	  // Substitute loop variables with constants in expressions
215	  class SubstituteLoopVars : public ExprMutator {
216	  public:
217	    const VarNode *vector_dim_var_;
218	    const VarNode *outer_dim_var_;
219	    bool is_2d_vectorizing_;
220	
221	    explicit SubstituteLoopVars(const VarNode *vector_dim_var,
222	                                const VarNode *outer_dim_var,
223	                                bool is_2d_vectorizing)
224	        : vector_dim_var_(vector_dim_var), outer_dim_var_(outer_dim_var),
225	          is_2d_vectorizing_(is_2d_vectorizing) {}
226	
227	    PrimExpr VisitExpr_(const VarNode *op) override {
228	      // Replace vector dim var with 0
229	      if (vector_dim_var_ != nullptr && op == vector_dim_var_) {
230	        return IntImm(DataType::Int(32), 0);
231	      }
232	      // Replace outer dim var with 0 if 2d vectorizing
233	      if (is_2d_vectorizing_ && outer_dim_var_ != nullptr &&
234	          op == outer_dim_var_) {
235	        return IntImm(DataType::Int(32), 0);
236	      }
237	      return GetRef<PrimExpr>(op);
238	    }
239	  };
240	
241	  Stmt VisitStmt_(const ForNode *op) override {
242	    // Sequence of store statements (handles both single stores and sequences)
243	    auto TryVectorizeStoreSeq =
244	        [&](Stmt stmt, PrimExpr total_elements,
245	            const std::unordered_set<const VarNode *> &parallel_vars,
246	            bool has_outer_serial, const VarNode *vector_dim,
247	            const VarNode *outer_dim = nullptr) -> Stmt {
248	      int64_t element_count = 0;
249	      if (!TryGetElementCount(total_elements, &element_count))
250	        return Stmt();
251	      const VarNode *old_vector = vector_dim_var_;
252	      const VarNode *old_outer = outer_dim_var_;
253	      vector_dim_var_ = vector_dim;
254	      outer_dim_var_ = outer_dim;
255	
256	      Stmt v = TryVectorizeBufferStoreSeq(stmt, element_count, parallel_vars,
257	                                          has_outer_serial);
258	
259	      vector_dim_var_ = old_vector;
260	      outer_dim_var_ = old_outer;
261	      return v;
262	    };
263	
264	    // Parallel cases
265	    if (op->kind == ForKind::kParallel) {
266	      // parallel -> (store | seq)
267	      {
268	        if (op->body.as<BufferStoreNode>() || op->body.as<SeqStmtNode>()) {
269	          int64_t extent = 0;
270	          if (TryGetElementCount(op->extent, &extent)) {
271	            vector_dim_extent_ = extent;
272	            outer_dim_extent_ = 1;
273	          }
274	          Stmt v =
275	              TryVectorizeStoreSeq(op->body, op->extent, {op->loop_var.get()},
276	                                   false, op->loop_var.as<VarNode>());
277	          vector_dim_extent_ = 0;
278	          outer_dim_extent_ = 0;
279	          if (v.defined())
280	            return v;
281	        }
282	      }
283	
284	      // parallel -> parallel -> (store | seq)
285	      const auto *inner_for = op->body.as<ForNode>();
286	      if (!inner_for || inner_for->kind != ForKind::kParallel) {
287	        // Not a 2D parallel nest and the 1D path above could not vectorize it:
288	        // lower this parallel loop to serial. Ascend has no native
289	        // parallel-for, so a surviving kParallel would reach codegen and trip
290	        // "Find undefined Variable v_thread".
291	        auto serial = make_object<ForNode>(*op);
292	        serial->kind = ForKind::kSerial;
293	        serial->body = VisitStmt(op->body);
294	        return Stmt(serial);
295	      }
296	
297	      const auto *third_for = inner_for->body.as<ForNode>();
298	      if (third_for && third_for->kind == ForKind::kParallel) {
299	        LOG(FATAL)
300	            << "Unsupported: 3D or higher dimensional parallel loops detected. "
301	            << "Only 1D and 2D parallel loops are supported for T.Parallel.";
302	      }
303	
304	      PrimExpr total_elements = inner_for->extent * op->extent;
305	      std::unordered_set<const VarNode *> parallel_vars = {
306	          op->loop_var.get(), inner_for->loop_var.get()};
307	
308	      if (inner_for->body.as<BufferStoreNode>() ||
309	          inner_for->body.as<SeqStmtNode>()) {
310	        int64_t inner_extent = 0;
311	        int64_t outer_extent = 0;
312	        if (TryGetElementCount(inner_for->extent, &inner_extent) &&
313	            TryGetElementCount(op->extent, &outer_extent)) {
314	          vector_dim_extent_ = inner_extent;
315	          outer_dim_extent_ = outer_extent;
316	        }
317	        Stmt v = TryVectorizeStoreSeq(
318	            inner_for->body, total_elements, parallel_vars, false,
319	            inner_for->loop_var.get(), op->loop_var.get());
320	        vector_dim_extent_ = 0;
321	        outer_dim_extent_ = 0;
322	        if (v.defined())
323	          return v;
324	      }
325	
326	      // 2D parallel nest that could not be vectorized (e.g. a compact->aligned
327	      // UB copy): lower both levels to serial instead of leaving kParallel
328	      // loops for codegen.
329	      auto outer = make_object<ForNode>(*op);
330	      outer->kind = ForKind::kSerial;
331	      auto inner = make_object<ForNode>(*inner_for);
332	      inner->kind = ForKind::kSerial;
333	      inner->body = VisitStmt(inner_for->body);
334	      outer->body = Stmt(inner);
335	      return Stmt(outer);
336	    }
337	
338	    // Serial cases
339	    if (op->kind == ForKind::kSerial) {
340	      const auto *inner_for = op->body.as<ForNode>();
341	      if (!inner_for || inner_for->kind != ForKind::kParallel) {
342	        return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
343	      }
344	      PrimExpr total_elements = inner_for->extent * op->extent;
345	      std::unordered_set<const VarNode *> parallel_vars = {
346	          inner_for->loop_var.get()};
347	
348	      // serial -> parallel -> (store | seq)
349	      if (inner_for->body.as<BufferStoreNode>() ||
350	          inner_for->body.as<SeqStmtNode>()) {
351	        int64_t inner_extent = 0;
352	        if (TryGetElementCount(inner_for->extent, &inner_extent)) {
353	          vector_dim_extent_ = inner_extent;
354	          outer_dim_extent_ = 1; // No outer parallel loop in this case
355	        }
356	        Stmt v =
357	            TryVectorizeStoreSeq(inner_for->body, total_elements, parallel_vars,
358	                                 true, inner_for->loop_var.as<VarNode>());
359	        vector_dim_extent_ = 0;
360	        outer_dim_extent_ = 0;
361	        if (!v.defined())
362	          return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
363	        auto op_copy = make_object<ForNode>(*op);
364	        op_copy->body = v;
365	        return Stmt(op_copy);
366	      }
367	    }
368	
369	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
370	  }
371	
372	  Stmt VisitStmt_(const BlockNode *op) override {
373	    // Save outer state
374	    auto saved_buffers = std::move(temp_buffers_);
375	    int saved_temp_id = temp_buffer_id_;
376	    const VarNode *saved_vector_dim = vector_dim_var_;
377	    const VarNode *saved_outer_dim = outer_dim_var_;
378	    bool saved_is_2d_vectorizing = is_2d_vectorizing_;
379	
380	    // Reset block-local state
381	    temp_buffers_.clear();
382	    temp_buffer_id_ = 0;
383	    vector_dim_var_ = nullptr;
384	    outer_dim_var_ = nullptr;
385	    is_2d_vectorizing_ = false;
386	
387	    // Visit body (vectorization happens here)
388	    Stmt new_body = VisitStmt(op->body);
389	
390	    // Attach temps to THIS block only
391	    Array<Buffer> allocs = op->alloc_buffers;
392	    for (const Buffer &buf : temp_buffers_) {
393	      allocs.push_back(buf);
394	    }
395	
396	    // Restore outer state
397	    temp_buffers_ = std::move(saved_buffers);
398	    temp_buffer_id_ = saved_temp_id;
399	    vector_dim_var_ = saved_vector_dim;
400	    outer_dim_var_ = saved_outer_dim;
401	    is_2d_vectorizing_ = saved_is_2d_vectorizing;
402	
403	    if (allocs.same_as(op->alloc_buffers) && new_body.same_as(op->body)) {
404	      return GetRef<Stmt>(op);
405	    }
406	
407	    return Block(op->iter_vars, op->reads, op->writes, op->name_hint, new_body,
408	                 op->init, allocs);
409	  }
