411	  // Generic Plan
412	  struct VectorPlan {
413	    int64_t inner_vec_len{0};
414	    int64_t outer_extent{0};
415	    const VarNode *outer_index_var{nullptr};
416	    bool is_2d_vectorizable{false};
417	  };
418	
419	  // Detect plan for vector, fill in the input plan
420	  bool DetectVectorPlan(const BufferStoreNode *store, int64_t element_count,
421	                        VectorPlan *plan) {
422	    Buffer output_buffer = store->buffer;
423	
424	    // Helper to check if an expression contains a specific variable
425	    auto ContainsVar = [](const PrimExpr &expr, const VarNode *var) -> bool {
426	      class VarChecker : public ExprVisitor {
427	      public:
428	        const VarNode *target_var_;
429	        bool found_{false};
430	
431	        explicit VarChecker(const VarNode *target_var)
432	            : target_var_(target_var) {}
433	
434	        void VisitExpr_(const VarNode *op) override {
435	          if (op == target_var_) {
436	            found_ = true;
437	          }
438	          ExprVisitor::VisitExpr_(op);
439	        }
440	      };
441	
442	      VarChecker checker(var);
443	      checker(expr);
444	      return checker.found_;
445	    };
446	
447	    /*----- 1D case -----*/
448	    if (output_buffer->shape.size() == 1 && store->indices.size() == 1) {
449	      if (!ContainsVar(store->indices[0], vector_dim_var_))
450	        return false;
451	      if (element_count <= 0)
452	        return false;
453	
454	      plan->inner_vec_len = element_count;
455	      plan->outer_extent = 1;
456	      plan->outer_index_var = nullptr;
457	      plan->is_2d_vectorizable = false;
458	      return true;
459	    }
460	
461	    /*----- 2D case -----*/
462	    if (vector_dim_var_ == nullptr)
463	      return false;
464	
465	    if (output_buffer->shape.size() == 2 && store->indices.size() == 2) {
466	      // Check if inner index contains the vector dimension variable
467	      bool is_l1_output = IsL1Buffer(output_buffer);
468	      if (!ContainsVar(store->indices[1], vector_dim_var_) && !is_l1_output)
469	        return false;
470	
471	      int64_t inner_vec_len = 0;
472	      // Use vector_dim_extent_ if available (actual loop extent), otherwise
473	      // fall back to buffer shape
474	      if (vector_dim_extent_ > 0) {
475	        inner_vec_len = vector_dim_extent_;
476	      } else {
477	        const IntImmNode *inner_imm = output_buffer->shape[1].as<IntImmNode>();
478	        if (inner_imm == nullptr)
479	          return false;
480	        inner_vec_len = inner_imm->value;
481	      }
482	
483	      if (inner_vec_len <= 0)
484	        return false;
485	      if (element_count % inner_vec_len != 0)
486	        return false;
487	
488	      plan->inner_vec_len = inner_vec_len;
489	      plan->outer_extent = element_count / inner_vec_len;
490	
491	      // Try to extract outer variable from the outer index
492	      plan->outer_index_var = store->indices[0].as<VarNode>();
493	
494	      // Check if outer index contains the outer dimension variable (for 2D
495	      // vectorization)
496	      plan->is_2d_vectorizable =
497	          (outer_dim_var_ != nullptr &&
498	           ContainsVar(store->indices[0], outer_dim_var_));
499	      return true;
500	    }
501	
502	    /*----- 3D db case -----*/
503	    if (output_buffer->shape.size() == 3 && store->indices.size() == 3) {
504	      if (!ContainsVar(store->indices[2], vector_dim_var_))
505	        return false;
506	
507	      int64_t inner_vec_len = 0;
508	      // Use vector_dim_extent_ if available (actual loop extent), otherwise
509	      // fall back to buffer shape
510	      if (vector_dim_extent_ > 0) {
511	        inner_vec_len = vector_dim_extent_;
512	      } else {
513	        const IntImmNode *inner_imm = output_buffer->shape[2].as<IntImmNode>();
514	        if (inner_imm == nullptr)
515	          return false;
516	        inner_vec_len = inner_imm->value;
517	      }
518	
519	      if (inner_vec_len <= 0)
520	        return false;
521	      if (element_count % inner_vec_len != 0)
522	        return false;
523	
524	      plan->inner_vec_len = inner_vec_len;
525	      plan->outer_extent = element_count / inner_vec_len;
526	      plan->outer_index_var = store->indices[1].as<VarNode>();
527	      plan->is_2d_vectorizable =
528	          (outer_dim_var_ != nullptr &&
529	           ContainsVar(store->indices[1], outer_dim_var_));
530	      return true;
531	    }
532	    return false;
533	  }
534	
535	  bool CheckExpressionSupports2DVectorization(
536	      const PrimExpr &expr,
537	      const std::unordered_set<const VarNode *> &parallel_vars) {
538	    if (vector_dim_var_ == nullptr || outer_dim_var_ == nullptr) {
539	      return false;
540	    }
541	    class BufferLoadCollector : public StmtExprVisitor {
542	    public:
543	      std::vector<const BufferLoadNode *> loads;
544	
545	      void VisitExpr_(const BufferLoadNode *op) override {
546	        loads.push_back(op);
547	        StmtExprVisitor::VisitExpr_(op);
548	      }
549	    };
550	
551	    BufferLoadCollector collector;
552	    collector(expr);
553	    bool container_2d_dim = false;
554	    for (const auto *load : collector.loads) {
555	      if (load->buffer->shape.size() == 2) {
556	        container_2d_dim = true;
557	      }
558	    }
559	
560	    auto ContainsVar = [](const PrimExpr &expr, const VarNode *var) -> bool {
561	      class VarChecker : public ExprVisitor {
562	      public:
563	        const VarNode *target_var_;
564	        bool found_{false};
565	        explicit VarChecker(const VarNode *target_var)
566	            : target_var_(target_var) {}
567	        void VisitExpr_(const VarNode *op) override {
568	          if (op == target_var_) {
569	            found_ = true;
570	          }
571	          ExprVisitor::VisitExpr_(op);
572	        }
573	      };
574	      VarChecker checker(var);
575	      checker(expr);
576	      return checker.found_;
577	    };
578	
579	    for (const auto *load : collector.loads) {
580	      bool uses_vector_dim = false;
581	      bool uses_outer_dim = false;
582	      for (const auto &idx : load->indices) {
583	        if (ContainsVar(idx, vector_dim_var_)) {
584	          uses_vector_dim = true;
585	        }
586	        if (ContainsVar(idx, outer_dim_var_)) {
587	          uses_outer_dim = true;
588	        }
589	      }
590	
591	      // If the buffer uses both dimensions, it's fine
592	      // If the buffer uses only one dimension, check if it can be broadcast
593	      if (!uses_vector_dim || !uses_outer_dim) {
594	        if (container_2d_dim) {
595	          return false;
596	        }
597	        int64_t broadcast_dim = 0;
598	        if (!CanBroadcast(load, parallel_vars, &broadcast_dim)) {
599	          return false;
600	        }
601	      }
602	    }
603	
604	    return true;
605	  }
606	
607	  Optional<Stmt> VectorizeStoreAsRowBody(
608	      const BufferStoreNode *store, int64_t inner_vec_len, int64_t outer_extent,
609	      bool is_2d, const std::unordered_set<const VarNode *> &parallel_vars) {
610	    Buffer output_buffer = store->buffer;
611	    bool is_global_output = IsGlobalMemoryBuffer(output_buffer);
612	    bool is_l0c_input = false;
613	    if (auto cast_node = store->value.as<CastNode>()) {
614	      if (auto l0c_node = cast_node->value.as<BufferLoadNode>()) {
615	        Buffer input_buffer = l0c_node->buffer;
616	        is_l0c_input = IsL0CBuffer(input_buffer);
617	      }
618	    }
619	
620	    bool saved_is_2d_vectorizing = is_2d_vectorizing_;
621	    is_2d_vectorizing_ = is_2d;
622	
623	    PrimExpr output_offset =
624	        CalculateBufferOffset(store->indices, output_buffer, parallel_vars);
625	
626	    // If output is in GM, create a temporary UB buffer sized for the
627	    // computation block
628	    Buffer actual_output_buffer = output_buffer;
629	    PrimExpr actual_output_offset = output_offset;
630	    Buffer temp_ub_buffer;
631	
632	    if (is_global_output && !is_l0c_input) {
633	      // Create a temporary UB buffer sized for the computation block (not the
634	      // full GM buffer)
635	      int64_t total_elements = inner_vec_len * outer_extent;
636	      temp_ub_buffer =
637	          CreateTempBufferLike(output_buffer, total_elements, inner_vec_len);
638	      actual_output_buffer = temp_ub_buffer;
639	      actual_output_offset =
640	          IntImm(DataType::Int(32), 0); // Start from beginning of temp buffer
641	    }
642	
643	    // Step 2: Detect all 1D buffers that can be broadcasted
644	    // Only collect broadcast buffers if there's no container 2d dim and output
645	    // is 2d
646	    class BroadcastableBufferCollector : public ExprVisitor {
647	    public:
648	      std::vector<BroadcastInfo> broadcast_infos;
649	      const std::unordered_set<const VarNode *> &parallel_vars_;
650	      int64_t inner_vec_len_;
651	      int64_t outer_extent_;
652	      AscendLowerParallelToVector *parent_;
653	
654	      BroadcastableBufferCollector(
655	          const std::unordered_set<const VarNode *> &parallel_vars,
656	          int64_t inner_vec_len, int64_t outer_extent,
657	          AscendLowerParallelToVector *parent)
658	          : parallel_vars_(parallel_vars), inner_vec_len_(inner_vec_len),
659	            outer_extent_(outer_extent), parent_(parent) {}
660	
661	      void VisitExpr_(const BufferLoadNode *op) override {
662	        // Only check 1D buffers
663	        if (op->buffer->shape.size() == 1) {
664	          int64_t broadcast_dim = 0;
665	          if (parent_->CanBroadcast(op, parallel_vars_, &broadcast_dim)) {
666	            BroadcastInfo info;
667	            info.load = op;
668	            info.broadcast_dim = broadcast_dim;
669	            info.outer_extent = outer_extent_;
670	            info.inner_vec_len = inner_vec_len_;
671	            broadcast_infos.push_back(info);
672	          }
673	        }
674	        ExprVisitor::VisitExpr_(op);
675	      }
676	    };
677	
678	    class UseDimChecker : public StmtExprVisitor {
679	    public:
680	      bool container_2d_dim = false;
681	
682	      void VisitExpr_(const BufferLoadNode *op) override {
683	        // Check if any index is not a simple variable or IntImm
684	        if (op->buffer->shape.size() == 2) {
685	          container_2d_dim = true;
686	        }
687	        StmtExprVisitor::VisitExpr_(op);
688	      }
689	    };
690	
691	    UseDimChecker dim_checker;
692	    dim_checker(store->value);
693	
694	    BroadcastableBufferCollector collector(parallel_vars, inner_vec_len,
695	                                           outer_extent, this);
696	    // Only collect broadcast buffers if there's no container 2d dim and output
697	    // is 2d
698	    if (!dim_checker.container_2d_dim && is_2d_vectorizing_) {
699	      collector(store->value);
700	    }
701	
702	    // Step 3: Create temp buffers for broadcasted 1D buffers and workspace
703	    // buffers
704	    Array<Stmt> broadcast_stmts;
705	    std::unordered_map<const BufferLoadNode *, Buffer> broadcast_buffer_map;
706	    std::unordered_map<const BufferLoadNode *, Buffer> workspace_buffer_map;
707	
708	    for (size_t i = 0; i < collector.broadcast_infos.size(); ++i) {
709	      collector.broadcast_infos[i].broadcast_buffer =
710	          CreateBroadcastBuffer(collector.broadcast_infos[i].load->buffer,
711	                                collector.broadcast_infos[i].outer_extent,
712	                                collector.broadcast_infos[i].inner_vec_len);
713	      collector.broadcast_infos[i].workspace_buffer =
714	          CreateBroadcastWorkspaceBuffer(
715	              collector.broadcast_infos[i].outer_extent,
716	              collector.broadcast_infos[i].inner_vec_len,
717	              collector.broadcast_infos[i].load->buffer->dtype);
718	      broadcast_buffer_map[collector.broadcast_infos[i].load] =
719	          collector.broadcast_infos[i].broadcast_buffer;
720	      workspace_buffer_map[collector.broadcast_infos[i].load] =
721	          collector.broadcast_infos[i].workspace_buffer;
722	    }
723	
724	    // Step 4: Generate broadcast calls
725	    for (size_t i = 0; i < collector.broadcast_infos.size(); ++i) {
726	      const auto &info = collector.broadcast_infos[i];
727	      Buffer broadcast_buffer = broadcast_buffer_map[info.load];
728	      Buffer workspace_buffer = workspace_buffer_map[info.load];
729	      Stmt broadcast_stmt = GenerateBroadcastStmt(
730	          info.load->buffer, broadcast_buffer, workspace_buffer,
731	          info.broadcast_dim, info.outer_extent, info.inner_vec_len);
732	      broadcast_stmts.push_back(broadcast_stmt);
733	    }
734	
735	    // Step 5: Replace 1D buffers with broadcasted ones in the expression
736	    class BufferLoadReplacer : public ExprMutator {
737	    public:
738	      const std::unordered_map<const BufferLoadNode *, Buffer>
739	          &broadcast_buffer_map_;
740	
741	      BufferLoadReplacer(const std::unordered_map<const BufferLoadNode *,
742	                                                  Buffer> &broadcast_buffer_map)
743	          : broadcast_buffer_map_(broadcast_buffer_map) {}
744	
745	      PrimExpr VisitExpr_(const BufferLoadNode *op) override {
746	        auto it = broadcast_buffer_map_.find(op);
747	        if (it != broadcast_buffer_map_.end()) {
748	          // Replace with load from broadcast buffer
749	          // Use [0] as index since the vectorized operation will handle
750	          // accessing all elements of the broadcast buffer as contiguous memory
751	          Array<PrimExpr> indicates;
752	          indicates.push_back(IntImm(DataType::Int(32), 0));
753	          indicates.push_back(IntImm(DataType::Int(32), 0));
754	          return BufferLoad(it->second, indicates);
755	        }
756	        return ExprMutator::VisitExpr_(op);
757	      }
758	    };
759	
760	    BufferLoadReplacer replacer(broadcast_buffer_map);
761	    PrimExpr new_value = replacer(store->value);
762	
763	    // Step 6: Do the normal pass with the modified expression
764	    Array<Stmt> row_stmts;
765	    row_stmts.insert(row_stmts.end(), broadcast_stmts.begin(),
766	                     broadcast_stmts.end());
767	
768	    int64_t total_elements =
769	        is_2d ? (inner_vec_len * outer_extent) : inner_vec_len;
770	    bool success = DecomposeExpression(
771	        new_value, actual_output_buffer, actual_output_offset, total_elements,
772	        parallel_vars, &row_stmts, is_2d, inner_vec_len);
773	
774	    is_2d_vectorizing_ = saved_is_2d_vectorizing;
775	    // A failed decomposition (e.g. a compact->aligned UB->UB copy that cannot
776	    // be lowered to copy_ub_to_ub) must bail regardless of the output scope so
777	    // VisitStmt_ falls back to a scalar serial loop.
778	    if (!success)
779	      return NullOpt;
780	    if (is_global_output && row_stmts.empty())
781	      return NullOpt;
782	
783	    // If output is in GM, add ascend_copy to copy from temp UB to GM
784	    if (is_global_output && !is_l0c_input) {
785	      Stmt copy_stmt = GenerateAscendCopy(temp_ub_buffer, output_buffer,
786	                                          actual_output_offset, output_offset,
787	                                          total_elements, is_2d);
788	      row_stmts.push_back(copy_stmt);
789	    }
790	
791	    if (row_stmts.size() == 1)
792	      return row_stmts[0];
793	    return SeqStmt::Flatten(row_stmts);
794	  }
795	
796	  Stmt TryVectorizeBufferStoreSeq(
797	      Stmt stmt, int64_t element_count,
798	      const std::unordered_set<const VarNode *> &parallel_vars,
799	      bool has_outer_serial) {
800	    // Handle both single BufferStore and SeqStmt
801	    Array<Stmt> stores_to_process;
802	    if (const auto *store = stmt.as<BufferStoreNode>()) {
803	      stores_to_process = {stmt};
804	    } else if (const auto *seq = stmt.as<SeqStmtNode>()) {
805	      stores_to_process = seq->seq;
806	    } else {
807	      return Stmt(); // Not a store or sequence
808	    }
809	
810	    // Find the first buffer store node as reference
811	    const BufferStoreNode *first_store = nullptr;
812	    for (const Stmt &s : stores_to_process) {
813	      if (auto st = s.as<BufferStoreNode>()) {
814	        first_store = st;
815	        break;
816	      }
817	    }
818	    if (first_store == nullptr)
819	      return Stmt();
820	
821	    VectorPlan plan;
822	    if (!DetectVectorPlan(first_store, element_count, &plan)) {
823	      return Stmt();
824	    }
825	
826	    if (plan.is_2d_vectorizable) {
827	      for (const Stmt &s : stores_to_process) {
828	        if (auto st = s.as<BufferStoreNode>()) {
829	          if (!CheckExpressionSupports2DVectorization(st->value,
830	                                                      parallel_vars)) {
831	            plan.is_2d_vectorizable = false;
832	            break;
833	          }
834	        }
835	      }
836	    }
837	
838	    Array<Stmt> bodies;
839	    for (const Stmt &s : stores_to_process) {
840	      if (auto st = s.as<BufferStoreNode>()) {
841	        // Must be compatible buffer store
842	        VectorPlan curr_plan;
843	        if (!DetectVectorPlan(st, element_count, &curr_plan) ||
844	            curr_plan.outer_extent != plan.outer_extent) {
845	          return Stmt();
846	        }
847	
848	        auto body_opt = VectorizeStoreAsRowBody(
849	            st, curr_plan.inner_vec_len, curr_plan.outer_extent,
850	            plan.is_2d_vectorizable, parallel_vars);
851	        if (!body_opt.defined())
852	          return Stmt();
853	        bodies.push_back(body_opt.value());
854	      } else {
855	        // Conservative: only handle pure BufferStore sequences for now.
856	        return Stmt();
857	      }
858	    }
859	    if (bodies.empty())
860	      return Stmt();
861	
862	    Stmt combined = (bodies.size() == 1) ? bodies[0] : SeqStmt::Flatten(bodies);
863	
864	    if (plan.is_2d_vectorizable || has_outer_serial || plan.outer_extent == 1) {
865	      return combined;
866	    }
867	
868	    Var outer_var("outer_broadcast_idx", DataType::Int(32));
869	    if (plan.outer_index_var != nullptr) {
870	      ReplaceVarExpr replacer(plan.outer_index_var, outer_var);
871	      combined = replacer(combined);
872	    }
873	
874	    return For(outer_var, IntImm(DataType::Int(32), 0),
875	               IntImm(DataType::Int(32), plan.outer_extent), ForKind::kSerial,
876	               combined);
877	  }
878	
879	  bool
880	  DecomposeExpression(const PrimExpr &expr, const Buffer &output_buffer,
881	                      const PrimExpr &output_offset, int64_t element_count,
882	                      const std::unordered_set<const VarNode *> &parallel_vars,
883	                      Array<Stmt> *statements, bool is_2d = false,
884	                      int64_t inner_vec_len = 0) {
885	
886	    // L0C->GM
887	    if (auto cast_node = expr.as<CastNode>()) {
888	      if (auto l0c_node = cast_node->value.as<BufferLoadNode>()) {
889	        Buffer input_buffer = l0c_node->buffer;
890	        PrimExpr input_offset = CalculateBufferOffset(
891	            l0c_node->indices, input_buffer, parallel_vars);
892	        auto stmt =
893	            GenerateAscendCopy(input_buffer, output_buffer, input_offset,
894	                               output_offset, element_count, is_2d);
895	        statements->push_back(stmt);
896	        return true;
897	      }
898	    }
899	
900	    // GM->UB GM->L1
901	    if (auto load = expr.as<BufferLoadNode>()) {
902	      Buffer input_buffer = load->buffer;
903	
904	      // Compact->aligned UB->UB copy (different inner/row width) cannot be
905	      // lowered to copy_ub_to_ub safely: the strided variant needs 32B-aligned
906	      // per-row UB addresses (sub-32B compact rows trap the VEC instruction),
907	      // and using the dst width mispacks rows. Bail so VisitStmt_ falls back to
908	      // a correct scalar serial loop.
909	      if (IsUnifiedBuffer(input_buffer) && IsUnifiedBuffer(output_buffer) &&
910	          input_buffer->shape.size() >= 2 && output_buffer->shape.size() >= 2) {
911	        const auto *src_inner = input_buffer->shape.back().as<IntImmNode>();
912	        const auto *dst_inner = output_buffer->shape.back().as<IntImmNode>();
913	        if (src_inner && dst_inner && src_inner->value != dst_inner->value) {
914	          return false;
915	        }
916	      }
917	
918	      PrimExpr input_offset =
919	          CalculateBufferOffset(load->indices, input_buffer, parallel_vars);
920	
921	      // calculate src_indices
922	      Array<PrimExpr> src_indices;
923	      SubstituteLoopVars substitutor(vector_dim_var_, outer_dim_var_,
924	                                     is_2d_vectorizing_);
925	      for (const auto &idx : load->indices) {
926	        src_indices.push_back(substitutor(idx));
927	      }
928	      auto stmt =
929	          GenerateAscendCopy(input_buffer, output_buffer, input_offset,
930	                             output_offset, element_count, is_2d, src_indices);
931	      statements->push_back(stmt);
932	      return true;
933	    }
934	
935	    Op unary_op_type;
936	
937	    Optional<Buffer> unary_input_buffer;
938	    PrimExpr unary_input_offset;
939	
940	    if (IsUnaryOp(expr, &unary_op_type, &unary_input_buffer,
941	                  &unary_input_offset, parallel_vars)) {
942	      auto stmt = GenerateUnaryVectorCall(
943	          unary_op_type, output_buffer, output_offset,
944	          unary_input_buffer.value(), unary_input_offset, element_count, is_2d);
945	      statements->push_back(stmt);
946	      return true;
947	    }
948	
949	    Op op_type;
950	    Array<PrimExpr> operands;
951	
952	    if (!IsBinaryOp(expr, &op_type, &operands)) {
953	      return false;
954	    }
955	
956	    ICHECK_EQ(operands.size(), 2);
957	
958	    bool left_is_simple = operands[0].as<BufferLoadNode>() ||
959	                          IsScalarLike(operands[0], parallel_vars);
960	    bool right_is_simple = operands[1].as<BufferLoadNode>() ||
961	                           IsScalarLike(operands[1], parallel_vars);
962	
963	    bool left_is_complex =
964	        IsBinaryOp(operands[0], nullptr, nullptr) ||
965	        IsUnaryOp(operands[0], nullptr, nullptr, nullptr, parallel_vars);
966	    bool right_is_complex =
967	        IsBinaryOp(operands[1], nullptr, nullptr) ||
968	        IsUnaryOp(operands[1], nullptr, nullptr, nullptr, parallel_vars);
969	
970	    if (left_is_simple && right_is_simple) {
971	      return HandleSimpleCase(op_type, operands, output_buffer, output_offset,
972	                              element_count, parallel_vars, statements, is_2d);
973	    }
974	
975	    if (left_is_simple && right_is_complex) {
976	      return HandleLeftSimpleRightComplex(
977	          op_type, operands, output_buffer, output_offset, element_count,
978	          parallel_vars, statements, is_2d, inner_vec_len);
979	    }
980	
981	    if (left_is_complex && right_is_simple) {
982	      return HandleLeftComplexRightSimple(
983	          op_type, operands, output_buffer, output_offset, element_count,
984	          parallel_vars, statements, is_2d, inner_vec_len);
985	    }
986	
987	    if (left_is_complex && right_is_complex) {
988	      Buffer lhs_tmp =
989	          CreateTempBufferLike(output_buffer, element_count, inner_vec_len);
990	      Buffer rhs_tmp =
991	          CreateTempBufferLike(output_buffer, element_count, inner_vec_len);
992	      PrimExpr lhs_tmp_offset = IntImm(DataType::Int(32), 0);
993	      PrimExpr rhs_tmp_offset = IntImm(DataType::Int(32), 0);
994	
995	      if (!DecomposeExpression(operands[0], lhs_tmp, lhs_tmp_offset,
996	                               element_count, parallel_vars, statements, is_2d,
997	                               inner_vec_len)) {
998	        return false;
999	      }
1000	
1001	      if (!DecomposeExpression(operands[1], rhs_tmp, rhs_tmp_offset,
1002	                               element_count, parallel_vars, statements, is_2d,
1003	                               inner_vec_len)) {
1004	        return false;
1005	      }
1006	
1007	      auto stmt = GenerateBinaryVectorCall(
1008	          op_type, output_buffer, output_offset, lhs_tmp, lhs_tmp_offset,
1009	          rhs_tmp, rhs_tmp_offset, element_count, is_2d);
1010	      statements->push_back(stmt);
1011	      return true;
1012	    }
1013	
1014	    return false;
1015	  }
1016	
1017	  bool IsUnaryOp(const PrimExpr &expr, Op *op_type,
1018	                 Optional<Buffer> *input_buffer, PrimExpr *input_offset,
1019	                 const std::unordered_set<const VarNode *> &parallel_vars) {
1020	    if (auto call = expr.as<CallNode>()) {
1021	      std::string op_name;
1022	
1023	      if (auto *op_ptr = call->op.as<OpNode>()) {
1024	        op_name = op_ptr->name;
1025	      } else {
1026	        return false;
1027	      }
1028	
1029	      auto it = kTIRUnaryOpMap.find(op_name);
1030	      if (it != kTIRUnaryOpMap.end()) {
1031	        if (op_type)
1032	          *op_type = it->second;
1033	      } else if (call->op.same_as(builtin::bitwise_not()) ||
1034	                 call->op.same_as(tl::ascend_bitwise_not())) {
1035	        if (op_type)
1036	          *op_type = tl::ascend_bitwise_not();
1037	      } else {
1038	        return false;
1039	      }
1040	
1041	      if (call->args.size() >= 1) {
1042	        if (auto load = call->args[0].as<BufferLoadNode>()) {
1043	          if (input_buffer)
1044	            *input_buffer = load->buffer;
1045	          if (input_offset)
1046	            *input_offset = CalculateBufferOffset(load->indices, load->buffer,
1047	                                                  parallel_vars);
1048	          return true;
1049	        }
1050	      }
1051	    }
1052	
1053	    if (auto max_node = expr.as<MaxNode>()) {
1054	      if (IsZero(max_node->a)) {
1055	        if (op_type)
1056	          *op_type = tl::ascend_relu();
1057	        if (auto load = max_node->b.as<BufferLoadNode>()) {
1058	          if (input_buffer)
1059	            *input_buffer = load->buffer;
1060	          if (input_offset)
1061	            *input_offset = CalculateBufferOffset(load->indices, load->buffer,
1062	                                                  parallel_vars);
1063	          return true;
1064	        }
1065	      }
1066	      if (IsZero(max_node->b)) {
1067	        if (op_type)
1068	          *op_type = tl::ascend_relu();
1069	        if (auto load = max_node->a.as<BufferLoadNode>()) {
1070	          if (input_buffer)
1071	            *input_buffer = load->buffer;
1072	          if (input_offset)
1073	            *input_offset = CalculateBufferOffset(load->indices, load->buffer,
1074	                                                  parallel_vars);
1075	          return true;
1076	        }
1077	      }
1078	    }
1079	    return false;
1080	  }
1081	
1082	  bool
1083	  HandleSimpleCase(const Op &op_type, const Array<PrimExpr> &operands,
1084	                   const Buffer &output_buffer, const PrimExpr &output_offset,
1085	                   int64_t element_count,
1086	                   const std::unordered_set<const VarNode *> &parallel_vars,
1087	                   Array<Stmt> *statements, bool is_2d = false) {
1088	    Buffer left_buffer;
1089	    PrimExpr left_offset;
1090	
1091	    if (auto load = operands[0].as<BufferLoadNode>()) {
1092	      left_buffer = load->buffer;
1093	      left_offset =
1094	          CalculateBufferOffset(load->indices, left_buffer, parallel_vars);
1095	    } else {
1096	      return false;
1097	    }
1098	
1099	    if (auto load = operands[1].as<BufferLoadNode>()) {
1100	      if (IsScalarAccess(load->indices, parallel_vars)) {
1101	        PrimExpr scalar_offset =
1102	            CalculateBufferOffset(load->indices, load->buffer, parallel_vars);
1103	        auto stmt = GenerateBufferScalarVectorCall(
1104	            op_type, output_buffer, output_offset, left_buffer, left_offset,
1105	            load->buffer, scalar_offset, element_count, is_2d);
1106	        statements->push_back(stmt);
1107	        return true;
1108	      } else {
1109	        PrimExpr right_offset =
1110	            CalculateBufferOffset(load->indices, load->buffer, parallel_vars);
1111	        auto stmt = GenerateBinaryVectorCall(
1112	            op_type, output_buffer, output_offset, left_buffer, left_offset,
1113	            load->buffer, right_offset, element_count, is_2d);
1114	        statements->push_back(stmt);
1115	        return true;
1116	      }
1117	
1118	    } else if (IsScalar(operands[1])) {
1119	      auto stmt = GenerateScalarVectorCall(
1120	          op_type, output_buffer, output_offset, left_buffer, left_offset,
1121	          operands[1], element_count, is_2d);
1122	      statements->push_back(stmt);
1123	      return true;
1124	    }
1125	
1126	    return false;
1127	  }
1128	
1129	  bool HandleLeftSimpleRightComplex(
1130	      const Op &op_type, const Array<PrimExpr> &operands,
1131	      const Buffer &output_buffer, const PrimExpr &output_offset,
1132	      int64_t element_count,
1133	      const std::unordered_set<const VarNode *> &parallel_vars,
1134	      Array<Stmt> *statements, bool is_2d = false, int64_t inner_vec_len = 0) {
1135	    Buffer left_buffer;
1136	    PrimExpr left_offset;
1137	
1138	    if (auto load = operands[0].as<BufferLoadNode>()) {
1139	      left_buffer = load->buffer;
1140	      left_offset =
1141	          CalculateBufferOffset(load->indices, left_buffer, parallel_vars);
1142	    } else {
1143	      return false;
1144	    }
1145	
1146	    Buffer tmp =
1147	        CreateTempBufferLike(output_buffer, element_count, inner_vec_len);
1148	    PrimExpr tmp_offset = IntImm(DataType::Int(32), 0);
1149	
1150	    if (!DecomposeExpression(operands[1], tmp, tmp_offset, element_count,
1151	                             parallel_vars, statements, is_2d, inner_vec_len)) {
1152	      return false;
1153	    }
1154	
1155	    auto stmt = GenerateBinaryVectorCall(op_type, output_buffer, output_offset,
1156	                                         left_buffer, left_offset, tmp,
1157	                                         tmp_offset, element_count, is_2d);
1158	    statements->push_back(stmt);
1159	    return true;
1160	  }
1161	
1162	  bool HandleLeftComplexRightSimple(
1163	      const Op &op_type, const Array<PrimExpr> &operands,
1164	      const Buffer &output_buffer, const PrimExpr &output_offset,
1165	      int64_t element_count,
1166	      const std::unordered_set<const VarNode *> &parallel_vars,
1167	      Array<Stmt> *statements, bool is_2d = false, int64_t inner_vec_len = 0) {
1168	    Buffer tmp =
1169	        CreateTempBufferLike(output_buffer, element_count, inner_vec_len);
1170	    PrimExpr tmp_offset = IntImm(DataType::Int(32), 0);
1171	
1172	    if (!DecomposeExpression(operands[0], tmp, tmp_offset, element_count,
1173	                             parallel_vars, statements, is_2d, inner_vec_len)) {
1174	      return false;
1175	    }
1176	
1177	    if (auto load = operands[1].as<BufferLoadNode>()) {
1178	      if (IsScalarAccess(load->indices, parallel_vars)) {
1179	        PrimExpr scalar_offset =
1180	            CalculateBufferOffset(load->indices, load->buffer, parallel_vars);
1181	        auto stmt = GenerateBufferScalarVectorCall(
1182	            op_type, output_buffer, output_offset, tmp, tmp_offset,
1183	            load->buffer, scalar_offset, element_count, is_2d);
1184	        statements->push_back(stmt);
1185	        return true;
1186	      } else {
1187	        PrimExpr right_offset =
1188	            CalculateBufferOffset(load->indices, load->buffer, parallel_vars);
1189	        auto stmt = GenerateBinaryVectorCall(
1190	            op_type, output_buffer, output_offset, tmp, tmp_offset,
1191	            load->buffer, right_offset, element_count, is_2d);
1192	        statements->push_back(stmt);
1193	        return true;
1194	      }
1195	
1196	    } else if (IsScalar(operands[1])) {
1197	      auto stmt = GenerateScalarVectorCall(op_type, output_buffer,
1198	                                           output_offset, tmp, tmp_offset,
1199	                                           operands[1], element_count, is_2d);
1200	      statements->push_back(stmt);
1201	      return true;
1202	    }
1203	
1204	    return false;
1205	  }
