1361	  PrimExpr CalculateBufferOffset(
1362	      const Array<PrimExpr> &indices, const Buffer &buffer,
1363	      const std::unordered_set<const VarNode *> &parallel_vars) {
1364	    if (indices.empty()) {
1365	      return IntImm(DataType::Int(32), 0);
1366	    }
1367	
1368	    // Substitute loop variables with 0 in all indices
1369	    SubstituteLoopVars substitutor(vector_dim_var_, outer_dim_var_,
1370	                                   is_2d_vectorizing_);
1371	    Array<PrimExpr> processed_indices;
1372	    for (const auto &idx : indices) {
1373	      processed_indices.push_back(substitutor(idx));
1374	    }
1375	
1376	    bool all_zero = true;
1377	    for (const auto &idx : processed_indices) {
1378	      if (auto imm = idx.as<IntImmNode>()) {
1379	        if (imm->value != 0) {
1380	          all_zero = false;
1381	          break;
1382	        }
1383	      } else {
1384	        all_zero = false;
1385	        break;
1386	      }
1387	    }
1388	
1389	    if (all_zero) {
1390	      return IntImm(DataType::Int(32), 0);
1391	    }
1392	
1393	    PrimExpr offset = processed_indices[0];
1394	    for (size_t i = 1; i < processed_indices.size(); i++) {
1395	      offset = offset * buffer->shape[i] + processed_indices[i];
1396	    }
1397	
1398	    return analyzer_->Simplify(offset);
1399	  }
