1401	  bool
1402	  IsScalarAccess(const Array<PrimExpr> &indices,
1403	                 const std::unordered_set<const VarNode *> &parallel_vars) {
1404	    if (vector_dim_var_ == nullptr)
1405	      return true;
1406	
1407	    // Check if any index contains the vector dimension variable
1408	    for (const auto &idx : indices) {
1409	      class VectorDimChecker : public ExprVisitor {
1410	      public:
1411	        const VarNode *target_var_;
1412	        bool found_{false};
1413	
1414	        explicit VectorDimChecker(const VarNode *target_var)
1415	            : target_var_(target_var) {}
1416	
1417	        void VisitExpr_(const VarNode *op) override {
1418	          if (op == target_var_) {
1419	            found_ = true;
1420	          }
1421	          ExprVisitor::VisitExpr_(op);
1422	        }
1423	      };
1424	
1425	      VectorDimChecker checker(vector_dim_var_);
1426	      checker(idx);
1427	      if (checker.found_) {
1428	        return false;
1429	      }
1430	    }
1431	    return true;
1432	  }
