1508	  // Check if a buffer load can be broadcast from 1D to 2D
1509	  bool CanBroadcast(const BufferLoadNode *load,
1510	                    const std::unordered_set<const VarNode *> &parallel_vars,
1511	                    int64_t *broadcast_dim) {
1512	    if (load->buffer->shape.size() != 1) {
1513	      return false; // Only 1D buffers can be broadcast
1514	    }
1515	
1516	    if (load->indices.size() != 1) {
1517	      return false; // Must have exactly 1 index for 1D buffer
1518	    }
1519	
1520	    const PrimExpr &index = load->indices[0];
1521	
1522	    // Check if the index is a simple variable (no offset or complex
1523	    // expressions)
1524	    if (auto var = index.as<VarNode>()) {
1525	      // Check if it's the vector dimension variable (broadcast along outer dim,
1526	      // axis=0) Source should be [1, inner_vec_len] and broadcast along axis 0
1527	      if (vector_dim_var_ != nullptr && var == vector_dim_var_) {
1528	        *broadcast_dim = 0; // Broadcast along axis 0 (outer dimension)
1529	        return true;
1530	      }
1531	      // Check if it's the outer dimension variable (broadcast along inner dim,
1532	      // axis=1) Source should be [outer_extent, 1] and broadcast along axis 1
1533	      if (outer_dim_var_ != nullptr && var == outer_dim_var_) {
1534	        *broadcast_dim = 1; // Broadcast along axis 1 (inner dimension)
1535	        return true;
1536	      }
1537	    }
1538	
1539	    // If the index is not a simple variable, it might have offset or be
1540	    // discrete access In that case, we should not use broadcasting and fall
1541	    // back to looping
1542	    return false;
1543	  }
