1545	  // Create a 2D view of a 1D buffer for broadcast operation
1546	  Buffer CreateBroadcastSourceBuffer(const Buffer &src_1d,
1547	                                     int64_t broadcast_dim) {
1548	    // Use the same data pointer and dtype as the source buffer
1549	    // but create a 2D shape with one dimension = 1
1550	    DataType dtype = src_1d->dtype;
1551	
1552	    int64_t src_elements = 0;
1553	    if (auto imm = src_1d->shape[0].as<IntImmNode>()) {
1554	      src_elements = imm->value;
1555	    } else {
1556	      LOG(FATAL) << "Source buffer shape must be constant for broadcast";
1557	    }
1558	
1559	    Array<PrimExpr> shape;
1560	    if (broadcast_dim == 0) {
1561	      // Broadcasting along axis 0 (outer dimension): view as [1, src_elements]
1562	      shape.push_back(IntImm(DataType::Int(32), 1));
1563	      shape.push_back(IntImm(DataType::Int(32), src_elements));
1564	    } else {
1565	      // Broadcasting along axis 1 (inner dimension): view as [src_elements, 1]
1566	      shape.push_back(IntImm(DataType::Int(32), src_elements));
1567	      shape.push_back(IntImm(DataType::Int(32), 1));
1568	    }
1569	
1570	    Buffer buf = Buffer(src_1d->data, // Use the same data pointer
1571	                        dtype, shape,
1572	                        /*strides=*/{},
1573	                        /*elem_offset=*/PrimExpr(0),
1574	                        /*name=*/src_1d->name + "_broadcast_view",
1575	                        /*data_alignment=*/0,
1576	                        /*offset_factor=*/0,
1577	                        /*buffer_type=*/kDefault);
1578	
1579	    return buf;
1580	  }
