1609	  // Create a broadcast workspace buffer with uint8 type for temporary storage
1610	  Buffer CreateBroadcastWorkspaceBuffer(int64_t outer_extent,
1611	                                        int64_t inner_vec_len,
1612	                                        DataType dst_dtype) {
1613	    // Use uint8 type for the workspace buffer
1614	    DataType dtype = DataType::UInt(8);
1615	
1616	    Var data("broadcast_workspace_" + std::to_string(temp_buffer_id_++) +
1617	                 "_data",
1618	             PointerType(PrimType(dtype), "shared.ub"));
1619	
1620	    // Workspace buffer should be 2x the size of the dst buffer
1621	    // Create 1D shape (vector operations expect contiguous buffers)
1622	    int64_t total_elements = outer_extent * inner_vec_len;
1623	    int64_t workspace_elements = 2 * total_elements;
1624	    Array<PrimExpr> shape;
1625	    shape.push_back(IntImm(DataType::Int(32), workspace_elements));
1626	
1627	    Buffer buf = Buffer(data, dtype, shape,
1628	                        /*strides=*/{},
1629	                        /*elem_offset=*/PrimExpr(0),
1630	                        /*name=*/data->name_hint,
1631	                        /*data_alignment=*/0,
1632	                        /*offset_factor=*/0,
1633	                        /*buffer_type=*/kDefault);
1634	
1635	    temp_buffers_.push_back(buf);
