1639	  // Generate broadcast statement to broadcast
1640	  Stmt GenerateBroadcastStmt(const Buffer &src_1d, const Buffer &dst_2d,
1641	                             const Buffer &workspace, int64_t broadcast_dim,
1642	                             int64_t outer_extent, int64_t inner_vec_len) {
1643	    // Format: tir.call_intrin("handle", tl.ascend_broadcast(),
1644	    // "Broadcast<{dtype}, 2, {axis}, false>",
1645	    //                         dst.access_ptr("w"), src.access_ptr("r"),
1646	    //                         tmp.access_ptr("r"), dim, dst_shape[0],
1647	    //                         dst_shape[1], ..., src_shape[0], ...)
1648	    Array<PrimExpr> broadcast_args;
1649	
1650	    // Create a 2D view of the source buffer for broadcast operation
1651	    Buffer src_2d_view = CreateBroadcastSourceBuffer(src_1d, broadcast_dim);
1652	
1653	    // 0. Template argument string
1654	    DataType dtype = src_1d->dtype;
1655	    std::string dtype_str = DTypeToAscendCString(src_1d->dtype);
1656	    std::string template_args =
1657	        dtype_str + ", 2, " + std::to_string(broadcast_dim) + ", false";
1658	    broadcast_args.push_back(StringImm("Broadcast<" + template_args + ">"));
1659	
1660	    // 1. dst buffer access ptr (1D buffer, but broadcast op treats it as 2D
1661	    // based on shape args)
1662	    int64_t total_elements = outer_extent * inner_vec_len;
1663	    broadcast_args.push_back(CreateAccessPtr(
1664	        dst_2d, dtype, IntImm(DataType::Int(32), 0), total_elements, 2));
1665	
1666	    // 2. src buffer access ptr (2D view)
1667	    int64_t src_elements = 0;
1668	    if (auto imm = src_1d->shape[0].as<IntImmNode>()) {
1669	      src_elements = imm->value;
1670	    } else {
1671	      LOG(FATAL) << "Source buffer shape must be constant for broadcast";
1672	    }
1673	    broadcast_args.push_back(CreateAccessPtr(
1674	        src_2d_view, dtype, IntImm(DataType::Int(32), 0), src_elements, 2));
1675	
1676	    // 3. tmp buffer access ptr (workspace buffer, 1D shape)
1677	    // Workspace buffer should be 2x the size of the dst buffer
1678	    int64_t workspace_elements = 2 * total_elements;
1679	    broadcast_args.push_back(CreateAccessPtr(workspace, DataType::UInt(8),
1680	                                             IntImm(DataType::Int(32), 0),
1681	                                             workspace_elements, 1));
1682	
1683	    // 4. dim (number of dimensions)
1684	    broadcast_args.push_back(IntImm(DataType::Int(32), 2));
1685	
1686	    // 5. dst shape array (explicit 2D shape for broadcast operation)
1687	    broadcast_args.push_back(IntImm(DataType::Int(32), outer_extent));
1688	    broadcast_args.push_back(IntImm(DataType::Int(32), inner_vec_len));
1689	
1690	    // 6. src shape array (explicit 2D shape for broadcast operation)
1691	    // Use the shape from the 2D view of the source buffer
1692	    broadcast_args.push_back(src_2d_view->shape[0]);
1693	    broadcast_args.push_back(src_2d_view->shape[1]);
1694	
1695	    PrimExpr broadcast_call =
1696	        Call(DataType::Handle(), tl::ascend_broadcast(), broadcast_args);
1697	    return Evaluate(broadcast_call);
1698	  }
1699	
1700	  // Structure to hold broadcast information
1701	  struct BroadcastInfo {
1702	    const BufferLoadNode *load;
1703	    Buffer broadcast_buffer;
1704	    Buffer workspace_buffer;
1705	    int64_t broadcast_dim;
1706	    int64_t outer_extent;
1707	    int64_t inner_vec_len;
1708	  };
1709	
1710	  bool IsScalar(const PrimExpr &expr) {
1711	    return expr.as<IntImmNode>() || expr.as<FloatImmNode>() ||
1712	           expr.as<VarNode>();
1713	  }
1714	
1715	  bool IsZero(const PrimExpr &expr) {
1716	    if (auto imm = expr.as<IntImmNode>()) {
1717	      return imm->value == 0;
1718	    }
1719	    if (auto imm = expr.as<FloatImmNode>()) {
1720	      return imm->value == 0.0;
1721	    }
1722	    return false;
1723	  }
1724	
1725	  // Check if a buffer is in Global Memory (GM)
1726	  bool IsGlobalMemoryBuffer(const Buffer &buffer) {
1727	    if (auto *ptr_type = buffer->data->type_annotation.as<PointerTypeNode>()) {
1728	      return ptr_type->storage_scope == "global" ||
1729	             ptr_type->storage_scope.empty();
1730	    }
1731	    // If there's no PointerType annotation, it's global by default
1732	    return true;
1733	  }
1734	
1735	  // Check if a buffer is Unified Buffer(UB)
1736	  bool IsUnifiedBuffer(const Buffer &buffer) {
1737	    if (auto *ptr_type = buffer->data->type_annotation.as<PointerTypeNode>()) {
1738	      return ptr_type->storage_scope == "shared.ub";
1739	    }
1740	    return false;
1741	  }
1742	
1743	  // Check if a buffer is L1
1744	  bool IsL1Buffer(const Buffer &buffer) {
1745	    if (auto *ptr_type = buffer->data->type_annotation.as<PointerTypeNode>()) {
1746	      return ptr_type->storage_scope == "shared.l1";
1747	    }
1748	    return false;
1749	  }
1750	
1751	  // Check if a buffer is L0C
1752	  bool IsL0CBuffer(const Buffer &buffer) {
1753	    if (auto *ptr_type = buffer->data->type_annotation.as<PointerTypeNode>()) {
1754	      return ptr_type->storage_scope == "wmma.accumulator";
1755	    }
1756	    return false;
1757	  }
1758	
1759	  // Generate ascend_copy call from UB to GM
1760	  Stmt GenerateAscendCopy(const Buffer &src_ub, const Buffer &dst_gm,
1761	                          const PrimExpr &src_offset,
1762	                          const PrimExpr &dst_offset, int64_t element_count,
1763	                          bool is_2d = false,
1764	                          const Array<PrimExpr> &src_indices = {}) {
1765	    // Create T.region expressions for ascend_copy
1766	    // The format is: T.region(buffer_load_with_indices, access_mask, extent0,
1767	    // extent1, ...) ascend_copy expects: tl.ascend_copy(src_region, dst_region,
1768	    // enable_relu)
1769	
1770	    // Create source region (UB) - start from [0, 0] with the temp buffer's
1771	    // shape
1772	    Array<PrimExpr> actual_src_indices;
1773	    Array<PrimExpr> src_extents;
1774	
1775	    bool is_global_output = IsGlobalMemoryBuffer(dst_gm);
1776	    if (src_indices.empty()) {
1777	      if (src_ub->shape.size() == 1) {
1778	        actual_src_indices.push_back(IntImm(DataType::Int(32), 0));
1779	        src_extents.push_back(IntImm(DataType::Int(32), element_count));
1780	      } else if (src_ub->shape.size() == 2) {
1781	        // Temp buffer has shape [outer_extent, inner_vec_len]
1782	        actual_src_indices.push_back(IntImm(DataType::Int(32), 0));
1783	        actual_src_indices.push_back(IntImm(DataType::Int(32), 0));
1784	        src_extents.push_back(src_ub->shape[0]); // outer_extent
1785	        src_extents.push_back(src_ub->shape[1]); // inner_vec_len
1786	      }
1787	    } else {
1788	      if (src_ub->shape.size() == 1) {
1789	        actual_src_indices = src_indices;
1790	        src_extents.push_back(IntImm(DataType::Int(32), element_count));
1791	      } else if (src_ub->shape.size() == 2) {
1792	        PrimExpr row = floordiv(src_offset, src_ub->shape[1]);
1793	        PrimExpr col = truncmod(src_offset, src_ub->shape[1]);
1794	        actual_src_indices.push_back(row);
1795	        actual_src_indices.push_back(col);
1796	        src_extents.push_back(dst_gm->shape[0]); // outer_extent
1797	        src_extents.push_back(dst_gm->shape[1]); // inner_vec_len
1798	      }
1799	    }
1800	
1801	    // Create source BufferLoad
1802	    PrimExpr src_load = BufferLoad(src_ub, actual_src_indices);
1803	
1804	    // Create destination region (GM) - use the computed offset
1805	    Array<PrimExpr> dst_indices;
1806	    Array<PrimExpr> dst_extents;
1807	
1808	    if (src_indices.empty()) {
1809	      if (dst_gm->shape.size() == 1) {
1810	        dst_indices.push_back(dst_offset);
1811	        dst_extents.push_back(IntImm(DataType::Int(32), element_count));
1812	      } else if (dst_gm->shape.size() == 2) {
1813	        // Convert linear offset to 2D indices
1814	        PrimExpr row = floordiv(dst_offset, dst_gm->shape[1]);
1815	        PrimExpr col = truncmod(dst_offset, dst_gm->shape[1]);
1816	        dst_indices.push_back(row);
1817	        dst_indices.push_back(col);
1818	        // Use the same extents as the source buffer (the tile size)
1819	        dst_extents.push_back(src_ub->shape[0]);
1820	        dst_extents.push_back(src_ub->shape[1]);
1821	      }
1822	    } else {
1823	      if (dst_gm->shape.size() == 1) {
1824	        dst_indices.push_back(IntImm(DataType::Int(32), 0));
1825	        dst_extents.push_back(IntImm(DataType::Int(32), element_count));
1826	      } else if (dst_gm->shape.size() == 2) {
1827	        dst_indices.push_back(IntImm(DataType::Int(32), 0));
1828	        dst_indices.push_back(IntImm(DataType::Int(32), 0));
1829	        dst_extents.push_back(dst_gm->shape[0]);
1830	        dst_extents.push_back(dst_gm->shape[1]);
1831	      }
1832	    }
1833	
1834	    // Create destination BufferLoad
1835	    PrimExpr dst_load = BufferLoad(dst_gm, dst_indices);
1836	
1837	    // Create T.region calls
1838	    // Format: T.region(buffer_load, access_mask, extent0, extent1, ...)
1839	    // access_mask: 1 for read, 2 for write
1840	
1841	    auto CreateRegionCall = [&](const PrimExpr &load, int access_mask,
1842	                                const Array<PrimExpr> &extents) -> PrimExpr {
1843	      Array<PrimExpr> args;
1844	      args.push_back(load);
1845	      args.push_back(IntImm(DataType::Int(32), access_mask));
1846	      for (const auto &ext : extents) {
1847	        args.push_back(ext);
1848	      }
1849	      return Call(DataType::Handle(), Op::Get("tl.region"), args);
1850	    };
1851	
1852	    PrimExpr src_region =
1853	        CreateRegionCall(src_load, 1, src_extents); // 1 = read
1854	    PrimExpr dst_region =
1855	        CreateRegionCall(dst_load, 2, dst_extents); // 2 = write
1856	
1857	    // Create the ascend_copy call
1858	    // Format: tir.call_intrin("handle", tir.op.Op.get("tl.ascend_copy"), src,
1859	    // dst, enable_relu)
1860	    Array<PrimExpr> copy_args;
1861	    copy_args.push_back(src_region);
1862	    copy_args.push_back(dst_region);
1863	    copy_args.push_back(Bool(false)); // enable_relu = false
1864	
1865	    PrimExpr copy_call =
1866	        Call(DataType::Handle(), Op::Get("tl.ascend_copy"), copy_args);
1867	
1868	    return Evaluate(copy_call);
1869	  }
1870	};
1871	
1872	using namespace tir::transform;
1873	
1874	tvm::transform::Pass AscendLowerParallelToVector() {
1875	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1876	    auto new_func = AscendLowerParallelToVector::Substitute(std::move(f));
1877	    return new_func;
1878	  };
1879	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendLowerParallelToVector", {});
1880	}
1881	
1882	TVM_REGISTER_GLOBAL("tl.transform.AscendLowerParallelToVector")
1883	    .set_body_typed(AscendLowerParallelToVector);
1884	
1885	} // namespace tl
1886	} // namespace tvm
